import {
  useConsent,
  useScreen,
  useTransaction,
} from "@auth0/auth0-acul-react/consent";
import type { ConsentMembers } from "@auth0/auth0-acul-js/consent";
import type {
  ScreenMembersOnConsent,
  TransactionMembers,
} from "@auth0/auth0-acul-js";

import { useSessionTimeout } from "@/hooks/useSessionTimeout";
import locales from "@/screens/consent/locales/es.json";

// ---------------------------------------------------------------------------
// Tiempo de expiración de sesión en milisegundos.
// Ajusta este valor para que coincida con el "Token Lifetime" configurado en:
// Auth0 Dashboard → Applications → [tu app] → Advanced Settings → OAuth.
// Default de Auth0 Universal Login: 30 minutos.
// ---------------------------------------------------------------------------
const SESSION_TIMEOUT_MS = 1 * 60 * 1000; // 30 minutos

export const useConsentManager = () => {
  const consent: ConsentMembers = useConsent();
  const screen: ScreenMembersOnConsent = useScreen();
  const transaction: TransactionMembers = useTransaction();

  const { texts } = screen;

  // Hook genérico de timeout — inicia el timer automáticamente al montar.
  //
  // clientId  → leído del contexto ACUL (consent.client.id). Auth0 lo usa para
  //             validar que returnTo esté en la lista de Allowed Logout URLs de esa app.
  //
  // returnTo  → URL de tu aplicación, definida por ambiente en el archivo .env:
  //               .env.development  → VITE_LOGOUT_RETURN_TO=http://localhost:3000
  //               .env.staging      → VITE_LOGOUT_RETURN_TO=https://staging.miapp.com
  //               .env.production   → VITE_LOGOUT_RETURN_TO=https://miapp.com
  //             Auth0 no expone redirect_uri en el contexto de las pantallas ACUL
  //             por razones de seguridad, por lo que se usa la variable de entorno.
  const { isSessionExpired, triggerExpiry, handleLogout } = useSessionTimeout({
    timeoutMs: SESSION_TIMEOUT_MS,
    clientId: consent.client.id,
    returnTo: import.meta.env.VITE_LOGOUT_RETURN_TO,
  });

  const handleAccept = async (): Promise<void> => {
    if (process.env.NODE_ENV === "development") {
      alert("[DEV ONLY] User accepted consent");
      return;
    }
    try {
      await consent.accept();
    } catch (error) {
      console.error("Consent accept failed:", error);
      // Si accept() falla (ej: state expirado / 400), muestra el modal
      triggerExpiry();
    }
  };

  const handleDeny = async (): Promise<void> => {
    if (process.env.NODE_ENV === "development") {
      alert("[DEV ONLY] User denied consent");
      return;
    }
    try {
      await consent.deny();
    } catch (error) {
      console.error("Consent deny failed:", error);
      // Si deny() falla (ej: state expirado / 400), muestra el modal
      triggerExpiry();
    }
  };

  return {
    consent,
    screen,
    transaction,
    texts,
    locales,
    isSessionExpired,
    handleAccept,
    handleDeny,
    handleLogout,
  };
};
