import React from "react";

interface GoogleIconProps {
  width?: number;
  height?: number;
  className?: string;
}

/**
 * Icono de Google usando imagen estática del CDN (GitHub Pages).
 * Se usa una <img> en lugar de SVG inline para evitar problemas de
 * tree-shaking o chunking de Vite que impedían mostrar el icono.
 */
export const GoogleIcon: React.FC<GoogleIconProps> = ({
  width = 20,
  height = 20,
  className,
}) => (
  <img
    src="https://ericrosalio-sketch.github.io/ACUL-Web/icons/google.svg"
    alt="Google"
    width={width}
    height={height}
    className={className}
    loading="eager"
  />
);
